-- 3) Gecmis tarihli rezervasyonlar (her otele 1, Status=Completed)
WITH OneRoom AS (
    SELECT hr.HotelId, hr.Id AS HotelRoomId, hr.PricePerNight, hr.ExtraGuestPricePerNight, rt.MaxGuests,
           ROW_NUMBER() OVER (PARTITION BY hr.HotelId ORDER BY hr.PricePerNight, hr.Id) AS roomrn
    FROM HotelRooms hr
    INNER JOIN RoomTypes rt ON rt.Id = hr.RoomTypeId
),
Sel AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY HotelId) AS rn
    FROM OneRoom
    WHERE roomrn = 1
)
INSERT INTO Reservations (HotelRoomId, UserId, CheckInDate, CheckOutDate, GuestCount, TotalPrice, PaymentMethod, Status, CreatedAt)
SELECT
    s.HotelRoomId,
    2 + ((s.rn - 1) % 9),
    DATEADD(DAY, -(30 + s.rn * 6), CAST(GETDATE() AS date)),
    DATEADD(DAY, -(30 + s.rn * 6) + (2 + (s.rn % 3)), CAST(GETDATE() AS date)),
    CASE WHEN s.MaxGuests >= 2 THEN 2 ELSE 1 END,
    CAST((2 + (s.rn % 3)) * s.PricePerNight
         + (2 + (s.rn % 3)) * s.ExtraGuestPricePerNight * (CASE WHEN s.MaxGuests >= 2 THEN 1 ELSE 0 END) AS decimal(10,2)),
    CASE s.rn % 3 WHEN 0 THEN N'Nakit' WHEN 1 THEN N'Kredi Kartı' ELSE N'Banka Kartı' END,
    N'Completed',
    DATEADD(DAY, -(45 + s.rn * 6), CAST(GETDATE() AS date))
FROM Sel s
GO

-- 4) Her otele 1 gercek yorum (Rating 1-5; trigger AvgRating'i gunceller)
WITH Hn AS (
    SELECT h.Id AS HotelId, ROW_NUMBER() OVER (ORDER BY h.Id) AS rn
    FROM Hotels h
),
C AS (
    SELECT * FROM (VALUES
        (1,  N'Konum harikaydı, personel çok ilgiliydi. Kesinlikle tekrar geleceğiz.'),
        (2,  N'Oda tertemizdi ve manzara muhteşemdi. Kahvaltı beklediğimden iyiydi.'),
        (3,  N'Fiyat performans olarak çok başarılı, ailecek memnun kaldık.'),
        (4,  N'Deniz manzaralı odamız ferahtı, resepsiyon güler yüzlüydü.'),
        (5,  N'Havuz ve spa alanı çok keyifliydi, yemekler lezzetliydi.'),
        (6,  N'Sessiz ve huzurlu bir tatil geçirdik, yatak çok rahattı.'),
        (7,  N'Ulaşımı kolaydı, merkeze yakın. Personel her konuda yardımcı oldu.'),
        (8,  N'Çocuklar için aktiviteler güzeldi, biz de dinlenme fırsatı bulduk.'),
        (9,  N'Temizlik ve hijyen üst düzeydi, tekrar tercih ederim.'),
        (10, N'Akşam yemekleri çeşit doluydu, manzara eşliğinde harikaydı.'),
        (11, N'Odalar geniş ve aydınlıktı, banyo yeniydi. Çok memnun kaldık.'),
        (12, N'Genel olarak güzel bir deneyimdi, küçük aksaklıklar dışında sorun yoktu.')
    ) v(cn, txt)
)
INSERT INTO Reviews (HotelId, UserId, Rating, Comment, CreatedAt, IsApproved, ApprovedAt)
SELECT
    Hn.HotelId,
    2 + ((Hn.rn - 1) % 9),
    CASE WHEN Hn.rn % 5 = 0 THEN 4 ELSE 5 END,
    c.txt,
    DATEADD(DAY, -(15 + Hn.rn * 4), CAST(GETDATE() AS date)),
    1,
    GETDATE()
FROM Hn
INNER JOIN C ON c.cn = ((Hn.rn - 1) % 12) + 1
GO
